<?php
declare(strict_types=1); namespace Theobroma\OneC\Http;
final class ExchangeController {private \Closure $query;private \Closure $success;public function __construct(private readonly bool $enabled,private readonly BasicAuthenticator $auth,callable $query,callable $success){$this->query=$query(...);$this->success=$success(...);}public function handle(string $mode,string $username,string $password):ExchangeResponse{if(!$this->enabled)return new ExchangeResponse(503,"failure\nExchange disabled");if(!$this->auth->valid($username,$password))return new ExchangeResponse(401,"failure\nUnauthorized",headers:['WWW-Authenticate'=>'Basic realm="Theobroma 1C"']);return match($mode){'checkauth'=>new ExchangeResponse(200,"success\ntheobroma_1c_session\n".bin2hex(random_bytes(16))),'init'=>new ExchangeResponse(200,"zip=no\nfile_limit=10485760"),'query'=>new ExchangeResponse(200,(string)($this->query)(),'application/xml; charset=UTF-8'),'success'=>$this->ack(),default=>new ExchangeResponse(400,"failure\nUnsupported mode")};}private function ack():ExchangeResponse{($this->success)();return new ExchangeResponse(200,'success');}}
